const fs = require('fs');
const path = require('path');
const os = require('os');

function projectRoot() {
  return process.env.TIKTOK_WORKFLOW_ROOT
    || process.env.PROJECT_ROOT
    || path.join(os.homedir(), 'Downloads', 'tiktok-n8n-workflow-pack');
}

const body = $input.first().json || {};
const projectId = String(body.project_id || '').trim();
const feedback = String(body.feedback || '').trim();

let contextPath = String(body.concept_context_path || '').trim();
if (!contextPath && projectId) {
  contextPath = path.join(projectRoot(), '.n8n-local-cache', 'concept-context', 'concept_context_' + projectId + '.json');
}
if (!contextPath || !fs.existsSync(contextPath)) {
  throw new Error('director-rerun: 找不到 concept context 文件，project_id=' + projectId + ', path=' + contextPath);
}

const ctx = JSON.parse(fs.readFileSync(contextPath, 'utf8'));
return [{
  json: {
    project_id: ctx.project_id || projectId,
    product_name: ctx.product_name || '',
    product_desc: ctx.product_desc || '',
    target_market: ctx.target_market || '',
    target_language: ctx.target_language || '',
    creative_task_type: ctx.creative_task_type || '',
    reference_case_url: ctx.reference_case_url || '',
    image_1_path: ctx.image_1_path || (ctx.product_image_local_paths || [])[0] || '',
    image_2_path: ctx.image_2_path || (ctx.product_image_local_paths || [])[1] || '',
    product_image_local_paths: ctx.product_image_local_paths || [],
    product_images_meta: ctx.product_images_meta || [],
    submitted_at: ctx.submitted_at || ctx.created_at || '',
    created_at: ctx.created_at || '',
    concept_context_path: contextPath,
    feedback: feedback,
    rerun_at: new Date().toISOString(),
  },
}];

const fs = require('fs');
const path = require('path');

const row = $input.first().json || {};

function readImageBase64(imagePath) {
  if (!imagePath || !fs.existsSync(imagePath)) return { data: '', mimeType: 'image/jpeg' };
  const data = fs.readFileSync(imagePath).toString('base64');
  const ext = path.extname(imagePath).toLowerCase();
  const mimeType = ext === '.png' ? 'image/png' : ext === '.webp' ? 'image/webp' : 'image/jpeg';
  return { data, mimeType };
}

const img1 = readImageBase64(row.image_1_path);
const img2 = readImageBase64(row.image_2_path);

return [{
  json: {
    ...row,
    image_1_base64: img1.data,
    image_1_mime: img1.mimeType,
    image_2_base64: img2.data,
    image_2_mime: img2.mimeType,
  },
}];

const fs = require('fs');
const path = require('path');
const os = require('os');

function projectRoot() {
  return process.env.TIKTOK_WORKFLOW_ROOT
    || process.env.PROJECT_ROOT
    || path.join(os.homedir(), 'Downloads', 'tiktok-n8n-workflow-pack');
}
function readJsonIfExists(p) {
  try { return JSON.parse(fs.readFileSync(p, 'utf8')); } catch { return {}; }
}
function expandHome(p) {
  const t = String(p || '').trim();
  return t.startsWith('~/') ? path.join(os.homedir(), t.slice(2)) : t;
}
function readKeyFile(p) {
  try { return String(fs.readFileSync(expandHome(p), 'utf8') || '').trim(); } catch { return ''; }
}

const root = projectRoot();
const prompts = readJsonIfExists(path.join(root, 'prompts', 'prompt_center.json'));
const cfg = readJsonIfExists(path.join(root, 'config', 'local-config.json'));
const mappingFile = readJsonIfExists(path.join(root, 'config', 'creative_task_type_mapping.json'));

let geminiKey = readKeyFile(cfg.gemini_api_key_file);
if (!geminiKey) geminiKey = readKeyFile(path.join(os.homedir(), '.n8n', 'gemini-api-key'));
if (!geminiKey) geminiKey = String(process.env.GEMINI_API_KEY || '').trim();
if (!geminiKey) throw new Error('director-rerun: 找不到 Gemini API Key，请配置 config/local-config.json gemini_api_key_file 或 ~/.n8n/gemini-api-key');

const textModel = String(cfg.gemini_text_model || (prompts.gemini_models || {}).text || 'gemini-3-flash-preview').trim();
const geminiUrl = 'https://generativelanguage.googleapis.com/v1beta/models/' + textModel + ':generateContent?key=' + geminiKey;

const row = $input.first().json || {};
const mapping = { ...(prompts.creative_task_type_mapping || {}), ...mappingFile };

return [{
  json: {
    ...row,
    director_prompt: prompts.director || {},
    creative_task_type_mapping: mapping,
    gemini_url: geminiUrl,
  },
}];

function tpl(str, vars) {
  let out = String(str || '');
  for (const [k, v] of Object.entries(vars)) {
    out = out.split('{{' + k + '}}').join(v == null ? '' : String(v));
  }
  return out;
}

const row = $input.first().json || {};
const d = row.director_prompt || {};
const typeRules = (row.creative_task_type_mapping || {})[row.creative_task_type] || {};

const userText = tpl(d.user_template || '', {
  product_name: row.product_name,
  product_desc: row.product_desc ?? '',
  target_market: row.target_market,
  target_language: row.target_language,
  creative_task_type: row.creative_task_type,
  reference_case_url: row.reference_case_url ?? '',
});

const hardConstraintBlock = [
  '',
  '【Form 业务硬约束】',
  '- target_market 必须严格使用：' + (row.target_market || ''),
  '- target_language 必须严格使用：' + (row.target_language || ''),
  '- creative_task_type 必须严格使用：' + (row.creative_task_type || ''),
  '- creative_task_type_rules：' + JSON.stringify(typeRules, null, 2),
  '- 只有 creative_task_type 为空时，才允许模型自动判断视频类型。',
].join('\n');

const feedbackBlock = row.feedback ? [
  '',
  '【老板反馈（本次重跑必须采纳）】',
  row.feedback,
  '- 请根据以上反馈重新生成2个创意方向，调整后的方向必须与上一次明显不同。',
].join('\n') : '';

const parts = [{ text: userText + hardConstraintBlock + feedbackBlock }];
if (row.image_1_base64) parts.push({ inline_data: { mime_type: row.image_1_mime || 'image/jpeg', data: row.image_1_base64 } });
if (row.image_2_base64) parts.push({ inline_data: { mime_type: row.image_2_mime || 'image/jpeg', data: row.image_2_base64 } });

return [{
  json: {
    ...row,
    gemini_request_body: {
      system_instruction: { parts: [{ text: d.system_instruction || '' }] },
      contents: [{ role: 'user', parts }],
      generationConfig: d.generation_config || { responseMimeType: 'application/json' },
    },
  },
}];

const rawText = $json?.candidates?.[0]?.content?.parts?.[0]?.text;
if (!rawText) throw new Error('Gemini 返回里没有 candidates[0].content.parts[0].text');

function extractJsonText(text) {
  const tick = String.fromCharCode(96);
  const fence = tick + tick + tick;
  const fencedJson = new RegExp(fence + 'json\\s*([\\s\\S]*?)\\s*' + fence, 'i');
  const fencedAny = new RegExp(fence + '\\s*([\\s\\S]*?)\\s*' + fence, 'i');
  const fenced = text.match(fencedJson) || text.match(fencedAny);
  if (fenced?.[1]) return fenced[1].trim();
  const startObj = text.indexOf('{');
  const endObj = text.lastIndexOf('}');
  if (startObj >= 0 && endObj > startObj) return text.slice(startObj, endObj + 1).trim();
  return text.trim();
}

let parsed;
try {
  parsed = JSON.parse(extractJsonText(rawText));
} catch (e) {
  const _rawSnip = String(rawText || '').replace(/Authorization:[^\n\r]+/gi,'[REDACTED]').replace(/Bearer\s+\S+/gi,'[REDACTED]').replace(/AIzaSy[A-Za-z0-9_-]{30,}/g,'[REDACTED]').replace(/sk-[A-Za-z0-9]{20,}/g,'[REDACTED]').replace(/Kie[A-Za-z0-9_-]{10,}/g,'[REDACTED]').slice(0,80);
  throw new Error('NON_JSON_MODEL_RESPONSE: 模型返回了非合法 JSON。内容前80字：' + _rawSnip + '…\n解析错误：' + e.message);
}
const result = Array.isArray(parsed) ? (parsed[0] || {}) : (parsed || {});

const ctx = $('导演请求体组装_重跑').first().json || {};
const creativeTaskType = ctx.creative_task_type || '';
const typeRules = (ctx.creative_task_type_mapping || {})[creativeTaskType] || {};

const rawConcepts = Array.isArray(result.creative_concepts) ? result.creative_concepts : [];
const creativeConcepts = rawConcepts.map((concept, index) => ({
  concept_id: concept.concept_id || ('concept_' + String(index + 1).padStart(2, '0')),
  concept_name: concept.concept_name || concept.direction_name || ('创意方向 ' + (index + 1)),
  creative_form: concept.creative_form || concept.video_type || '',
  video_type: typeRules.video_type || concept.video_type || '',
  core_selling_angle: concept.core_selling_angle || concept.visual_hook || '',
  target_user: concept.target_user || concept.audience_focus || '',
  pain_point: concept.pain_point || '',
  usage_scene: concept.usage_scene || concept.scene_atmosphere || '',
  visual_expression: concept.visual_expression || concept.camera_performance || '',
  hook_strategy: concept.hook_strategy || concept.visual_hook || '',
  why_it_fits_tiktok: concept.why_it_fits_tiktok || concept.scene_atmosphere || '',
  recommended_grid: typeRules.recommended_grid || concept.recommended_grid || '6_grid',
  risk_notes: concept.risk_notes || '',
  score: concept.score || {},
  original_direction_name: concept.direction_name || '',
  original_payload: concept,
}));
const recommendedGrid = typeRules.recommended_grid || creativeConcepts[0]?.recommended_grid || '6_grid';

return [{
  json: {
    ...ctx,
    creative_concepts: creativeConcepts,
    creative_concepts_json: JSON.stringify(creativeConcepts),
    concept_count: creativeConcepts.length,
    recommended_grid: recommendedGrid,
    product_understanding_json: JSON.stringify(result.product_understanding || {}),
    audience_persona_json: JSON.stringify(result.audience_persona || {}),
    tiktok_content_strategy_json: JSON.stringify(result.tiktok_content_strategy || {}),
    director_status: 'concept_regenerated',
  },
}];

const fs = require('fs');
const path = require('path');

const row = $input.first().json || {};
const contextPath = row.concept_context_path;
if (!contextPath) throw new Error('director-rerun: 缺少 concept_context_path');

let existingCtx = {};
try { existingCtx = JSON.parse(fs.readFileSync(contextPath, 'utf8')); } catch {}

const creativeConcepts = Array.isArray(row.creative_concepts) ? row.creative_concepts : [];
const updatedCtx = {
  ...existingCtx,
  creative_concepts: creativeConcepts,
  creative_concepts_json: JSON.stringify(creativeConcepts),
  concept_count: creativeConcepts.length,
  recommended_grid: row.recommended_grid || existingCtx.recommended_grid || '6_grid',
  product_understanding_json: row.product_understanding_json || existingCtx.product_understanding_json || '{}',
  audience_persona_json: row.audience_persona_json || existingCtx.audience_persona_json || '{}',
  tiktok_content_strategy_json: row.tiktok_content_strategy_json || existingCtx.tiktok_content_strategy_json || '{}',
  status: 'waiting_for_concept_selection',
  last_rerun_at: new Date().toISOString(),
  last_rerun_feedback: row.feedback || '',
  updated_at: new Date().toISOString(),
};

const tmpPath = contextPath + '.tmp';
fs.writeFileSync(tmpPath, JSON.stringify(updatedCtx, null, 2));
fs.renameSync(tmpPath, contextPath);

return [{
  json: {
    project_id: row.project_id || existingCtx.project_id || '',
    concept_count: creativeConcepts.length,
    status: 'waiting_for_concept_selection',
    concept_context_path: contextPath,
    concepts_summary: creativeConcepts.map(c => ({
      concept_id: c.concept_id,
      concept_name: c.concept_name,
      video_type: c.video_type,
    })),
    rerun_at: row.rerun_at || new Date().toISOString(),
    feedback_applied: row.feedback || '',
  },
}];
